#include <bits/stdc++.h>
using namespace std;
class Solution {public:long long getMaxFunctionValue(vector<int>& receiver,long long k){int n=receiver.size(),B=0;while((1LL<<B)<=k&&B<62)++B;vector<vector<int>> up(B,vector<int>(n));vector<vector<long long>> sum(B,vector<long long>(n));for(int i=0;i<n;++i){up[0][i]=receiver[i];sum[0][i]=receiver[i];}for(int b=1;b<B;++b)for(int i=0;i<n;++i){up[b][i]=up[b-1][up[b-1][i]];sum[b][i]=sum[b-1][i]+sum[b-1][up[b-1][i]];}long long ans=0;for(int i=0;i<n;++i){long long cur=i;int v=i;for(int b=0;b<B;++b)if((k>>b)&1){cur+=sum[b][v];v=up[b][v];}ans=max(ans,cur);}return ans;}};
